	ChangeRequestsByDID(context.Context, *QueryChangeRequestsByDIDRequest) (*QueryChangeRequestsByDIDResponse, error)
	// ChangeHistory queries change history for a DID
	ChangeHistory(context.Context, *QueryChangeHistoryRequest) (*QueryChangeHistoryResponse, error)
