	Role(context.Context, *QueryRoleRequest) (*QueryRoleResponse, error)
	// AllRoles queries all roles
	AllRoles(context.Context, *QueryAllRolesRequest) (*QueryAllRolesResponse, error)
	// RoleAssignments queries role assignments for an address
	RoleAssignments(context.Context, *QueryRoleAssignmentsRequest) (*QueryRoleAssignmentsResponse, error)
	// HasPermission checks if an address has a specific permission
	HasPermission(context.Context, *QueryHasPermissionRequest) (*QueryHasPermissionResponse, error)
	// MultisigWallet queries a multisig wallet by ID
	MultisigWallet(context.Context, *QueryMultisigWalletRequest) (*QueryMultisigWalletResponse, error)
	// AllMultisigWallets queries all multisig wallets
	AllMultisigWallets(context.Context, *QueryAllMultisigWalletsRequest) (*QueryAllMultisigWalletsResponse, error)
	// MultisigProposal queries a multisig proposal by ID
	MultisigProposal(context.Context, *QueryMultisigProposalRequest) (*QueryMultisigProposalResponse, error)
	// MultisigProposalsByWallet queries proposals for a wallet
	MultisigProposalsByWallet(context.Context, *QueryMultisigProposalsByWalletRequest) (*QueryMultisigProposalsByWalletResponse, error)
	// TimeLockedAction queries a time-locked action by ID
	TimeLockedAction(context.Context, *QueryTimeLockedActionRequest) (*QueryTimeLockedActionResponse, error)
	// AllTimeLockedActions queries all time-locked actions
	AllTimeLockedActions(context.Context, *QueryAllTimeLockedActionsRequest) (*QueryAllTimeLockedActionsResponse, error)
	// EmergencyAdmin queries an emergency admin by address
	EmergencyAdmin(context.Context, *QueryEmergencyAdminRequest) (*QueryEmergencyAdminResponse, error)
	// AllEmergencyAdmins queries all emergency admins
	AllEmergencyAdmins(context.Context, *QueryAllEmergencyAdminsRequest) (*QueryAllEmergencyAdminsResponse, error)
	// ValidatorRotation queries a validator rotation by address
	ValidatorRotation(context.Context, *QueryValidatorRotationRequest) (*QueryValidatorRotationResponse, error)
	// Session queries a session by ID
	Session(context.Context, *QuerySessionRequest) (*QuerySessionResponse, error)
	// SessionsByAddress queries sessions for an address
	SessionsByAddress(context.Context, *QuerySessionsByAddressRequest) (*QuerySessionsByAddressResponse, error)
	// RateLimit queries rate limit config for an address
	RateLimit(context.Context, *QueryRateLimitRequest) (*QueryRateLimitResponse, error)
